{"action": "replace_code", "code": "def solve(data):
    left, right = data['base']
    if left >= right:
        return []

    blocked = []
    for a, b in data['blocked']:
        if a < b:
            # Обрезаем блокировку до границ base
            start = max(left, a)
            end = min(right, b)
            if start < end:
                blocked.append([start, end])

    # Сортируем блокировки по началу
    blocked.sort()

    result = []
    current_start = left

    for block_start, block_end in blocked:
        if block_start >= current_start:
            # Блок начинается после или в точке текущего начала
            if block_start > current_start:
                result.append([current_start, block_start])
            current_start = max(current_start, block_end)
        else:
            # Блок начинается раньше текущего начала (невозможно после сортировки, если логика верна, но на всякий случай)
            current_start = max(current_start, block_start)

    # Добавляем оставшуюся часть после всех блоков
    if current_start < right:
        result.append([current_start, right])

    return result
